-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "8ada5091-a172-1555-f3ee-36b16f00e0be", "before": {"stem": "Which equation describes the line graphed below?", "choices": [{"key": "A", "text": "3x + 2y = 6"}, {"key": "B", "text": "2x + 3y = 6"}, {"key": "C", "text": "3x − 2y = 6"}, {"key": "D", "text": "y = 3x + 2\nto"}], "correct": "A", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p8-q35", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 8", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "Which equation describes the line shown in the graph?", "choices": [{"key": "A", "text": "3x + 2y = 6"}, {"key": "B", "text": "2x + 3y = 6"}, {"key": "C", "text": "3x − 2y = 6"}, {"key": "D", "text": "y = 3x + 2"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The graph passes through (0,3) and (2,0). Its slope is (0 − 3)/(2 − 0) = −3/2 and its y-intercept is 3. Thus y = −3x/2 + 3, or 3x + 2y = 6.", "correct": "A"}, {"id": "42023659-d382-865a-80ae-05cbd582fc6f", "before": {"stem": "Q54. Given the graph of the function f below, which equation correctly represents\n f(x)?", "choices": [{"key": "A", "text": "f(x) = x² − 4x + 1"}, {"key": "B", "text": "f(x) = x² + 4x + 1"}, {"key": "C", "text": "f(x) = x² − 4x − 1"}, {"key": "D", "text": "f(x) = x² + 4x − 1 [Projectile — Peak Time] Ghoneem"}], "correct": "B", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00053", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 12", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "Which equation represents the parabola shown in the graph?", "choices": [{"key": "A", "text": "f(x) = x² − 4x + 1"}, {"key": "B", "text": "f(x) = x² + 4x + 1"}, {"key": "C", "text": "f(x) = x² − 4x − 1"}, {"key": "D", "text": "f(x) = x² + 4x − 1"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The parabola opens upward, has vertex (−2,−3), and passes through (0,1). Therefore f(x) = (x + 2)² − 3 = x² + 4x + 1, choice B.", "correct": "B"}, {"id": "6ea81a14-c958-830c-d582-7a6502bb9f8d", "before": {"stem": "Given the graph of the function f below, which equation correctly represents\nf(x)?", "choices": [{"key": "A", "text": "f(x) = x² − 4x + 1"}, {"key": "B", "text": "f(x) = x² + 4x + 1"}, {"key": "C", "text": "f(x) = x² − 4x − 1"}, {"key": "D", "text": "f(x) = x² + 4x − 1"}], "correct": "B", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p12-q54", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 12", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "Which equation represents the parabola shown in the graph?", "choices": [{"key": "A", "text": "f(x) = x² − 4x + 1"}, {"key": "B", "text": "f(x) = x² + 4x + 1"}, {"key": "C", "text": "f(x) = x² − 4x − 1"}, {"key": "D", "text": "f(x) = x² + 4x − 1"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The parabola opens upward, has vertex (−2,−3), and passes through (0,1). Therefore f(x) = (x + 2)² − 3 = x² + 4x + 1, choice B.", "correct": "B"}, {"id": "07daa6be-ad8a-6d50-06e9-7f9dff1f35f3", "before": {"stem": "The box-and-whisker plot below shows pumpkin weights at a fair. According\nto the plot, what is the median weight?", "choices": [{"key": "A", "text": "15 lbs"}, {"key": "B", "text": "30 lbs"}, {"key": "C", "text": "60 lbs"}, {"key": "D", "text": "95 lbs"}], "correct": "B", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p29-q144", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 29", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "The box-and-whisker plot shows pumpkin weights at a fair. What is the median weight?", "choices": [{"key": "A", "text": "15 lbs"}, {"key": "B", "text": "30 lbs"}, {"key": "C", "text": "60 lbs"}, {"key": "D", "text": "95 lbs"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The median is the vertical line inside the box. In this plot it is at 30 pounds. The whiskers mark 15 and 95, while the box extends from 22 to 60; these are not the median.", "correct": "B"}, {"id": "7dfe267a-7ab9-e591-690b-818d8171cdf9", "before": {"stem": "Q144. The box-and-whisker plot below shows pumpkin weights at a fair. According\n to the plot, what is the median weight?", "choices": [{"key": "A", "text": "15 lbs"}, {"key": "B", "text": "30 lbs"}, {"key": "C", "text": "60 lbs"}, {"key": "D", "text": "95 lbs"}], "correct": "B", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00140", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 29", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "The box-and-whisker plot shows pumpkin weights at a fair. What is the median weight?", "choices": [{"key": "A", "text": "15 lbs"}, {"key": "B", "text": "30 lbs"}, {"key": "C", "text": "60 lbs"}, {"key": "D", "text": "95 lbs"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "The median is the vertical line inside the box. In this plot it is at 30 pounds. The whiskers mark 15 and 95, while the box extends from 22 to 60; these are not the median.", "correct": "B"}, {"id": "22dd44a6-88a9-ae79-011f-ef0c5281aacf", "before": {"stem": "Q145. In the scatter plot below, at what x-value is the difference between the line\n of best fit and the actual point the greatest? Ghoneem\n 01116004434", "choices": [{"key": "A", "text": "9"}, {"key": "B", "text": "5"}, {"key": "C", "text": "14"}, {"key": "D", "text": "3"}], "correct": "A", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00141", "source": "/workspace/scratch/e379d1a7362b/audit-sources/DOC-20260623-WA0016_260909_203219.pdf; physical page 29", "review_note": "Original graph visually checked, recovered as a direct source crop, and all choices independently evaluated.", "release": true, "fields": {"stem": "At which listed x-value is the absolute vertical difference between the observed point and the line of best fit greatest?", "choices": [{"key": "A", "text": "9"}, {"key": "B", "text": "5"}, {"key": "C", "text": "14"}, {"key": "D", "text": "3"}], "assets_patch": {"figure": "data:image/jpeg;base64,"}}, "explanation": "Compare each point’s vertical distance from the dashed fitted line. At x = 9 the observed point is near y = 28 and the fitted value is near 21.5, a difference of about 6.5. The points at x = 3, 5, and 14 lie much closer to the line. Thus the largest absolute residual is at x = 9.", "correct": "A"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260928'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260928')) AS result;
